<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {requestWalkinDetails} from '../../../api/cc-report-walkin';
const props=defineProps({lead:{type:Object,required:true}}),emit=defineEmits(['close']);
const dialog=ref(null),data=ref(null),busy=ref(false),error=ref(''),controller=new AbortController();
async function load(refresh=false){busy.value=true;error.value='';try{data.value=await requestWalkinDetails({lead:props.lead.name},controller.signal,refresh);}catch(e){if(e.name!=='AbortError')error.value=e.message;}finally{busy.value=false;}}
function fileUrl(value){try{const url=new URL(value,window.location.origin);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}}
onMounted(()=>{dialog.value.showModal();load();});onBeforeUnmount(()=>controller.abort());
</script>
<template><dialog ref="dialog" class="cc-report-dialog cc-visit-details" @close="emit('close')"><header><div><h2>PD Form Images — {{lead.lead_name||lead.name}}</h2><p>{{lead.name}}</p></div><button @click="dialog.close()">Close</button></header><p v-if="busy" role="status">Loading PD forms and visit history…</p><p v-if="error" role="alert" class="cc-error">{{error}} <button @click="load(true)">Retry</button></p><template v-if="data"><dl><div><dt>Patient</dt><dd>{{data.patient||'Not linked'}}</dd></div><div><dt>PD number</dt><dd>{{data.pd_number||'Not recorded'}}</dd></div><div><dt>Visit status</dt><dd>{{data.status||'Not recorded'}}</dd></div><div><dt>Updated by / on</dt><dd>{{data.updated_by||'—'}} · {{data.updated_on||'—'}}</dd></div></dl><p v-if="data.remarks">{{data.remarks}}</p><div class="life-pd-image-grid"><a v-for="item in data.images||[]" :key="item.url" :href="fileUrl(item.url)" target="_blank" rel="noopener noreferrer" class="life-pd-image-card"><img v-if="fileUrl(item.thumb||item.url)" :src="fileUrl(item.thumb||item.url)" :alt="item.name||'PD form'" loading="lazy"><b>{{item.name||'PD form'}}</b><small>{{item.created}}</small></a></div><p v-if="!data.images?.length">No PD Form images were returned for this client.</p><h3>Branch visit history</h3><article v-for="(item,index) in data.history||[]" :key="index" class="cc-visit-history"><strong>{{item.by||'—'}} · {{item.on}}</strong><p>{{item.details}}</p></article><p v-if="!data.history?.length">No branch status history recorded.</p></template></dialog></template>
<style scoped>.cc-visit-details{width:min(1000px,94vw);max-height:88vh;border:1px solid #d5b66b;border-radius:12px;padding:20px;color:#16402d}.cc-visit-details::backdrop{background:#102c2266}header{display:flex;justify-content:space-between;gap:12px}h2{margin:0}dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}dt{font-size:12px;color:#69786c}dd{margin:4px 0}.life-pd-image-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.life-pd-image-card{display:grid;gap:6px;border:1px solid #d9e4db;border-radius:9px;padding:10px;text-decoration:none}.life-pd-image-card img{width:100%;height:160px;object-fit:contain}.cc-visit-history{border-top:1px solid #e2e9e3;padding:12px 0}.cc-visit-history p{white-space:pre-wrap}</style>
